js=r'''
var PTS=[[1,2,1],[2,3,1],[2,1.5,1],[3,2.5,1],[1.5,3,1],[-1,-1,-1],[-2,-0.5,-1],[0,-1.5,-1],[-1.5,-2,-1],[-0.5,-0.2,-1]];
function mg(w,b){var n=Math.hypot(w[0],w[1])||1,m=1e9;PTS.forEach(function(p){m=Math.min(m,p[2]*(w[0]*p[0]+w[1]*p[1]+b)/n);});return m;}
PAGE.marg=function(){var w=[0,0],b=0,ch=true,it=0;while(ch&&it<100){ch=false;it++;PTS.forEach(function(p){if(p[2]*(w[0]*p[0]+w[1]*p[1]+b)<=0){w=[w[0]+p[2]*p[0],w[1]+p[2]*p[1]];b+=p[2];ch=true;}});}
 var pm=mg(w,b),best=-1e9;for(var a=0;a<180;a+=0.5){var u=[Math.cos(a*Math.PI/180),Math.sin(a*Math.PI/180)],lo=1e9,hi=-1e9;PTS.forEach(function(p){var s=u[0]*p[0]+u[1]*p[1];if(p[2]>0)lo=Math.min(lo,s);else hi=Math.max(hi,s);});best=Math.max(best,(lo-hi)/2);}
 return {fly:best,robo:pm,flyTxt:best.toFixed(2),roboTxt:pm.toFixed(2)};};
'''
